import dev.ryanhcode.sable.sublevel.ServerSubLevel;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;
import org.joml.Vector3d;
import java.util.*;
final class RendezvousClientSmoke {
    private static int stage,ticks,at;private static volatile Throwable failure;private static Object identity,vehicle;private static UUID source,host,child;private static volatile boolean merged;
    static void tick(Minecraft mc,ServerSubLevel ship){ticks++;if(failure!=null)throw new AssertionError("Rendezvous server",failure);if(ticks>900)throw new AssertionError("Rendezvous timeout stage="+stage);
        if(stage==0){identity=SubLevelContainer.getContainer(mc.level).getSubLevel(ship.getUniqueId());vehicle=mc.player.getVehicle();require(vehicle!=null,"Fixture lost seat before rendezvous");stage=1;at=ticks;server(mc,()->{var level=ship.getLevel();var c=SubLevelContainer.getContainer(level);var cells=SpaceCells.get(level);var data=SpaceOrbitData.get(level.getServer());var cell=cells.forShip(ship.getUniqueId());source=cell.id();host=new UUID(Long.MIN_VALUE,Long.MIN_VALUE);io.github.astelev.around_planet.PlanetConfig.RENDEZVOUS_DISTANCE.set(0.0);c.physicsSystem().setPaused(true);var p=new BlockPos(1200,100,1200);level.setBlockAndUpdate(p,Blocks.IRON_BLOCK.defaultBlockState());var receiver=SubLevelAssemblyHelper.assembleBlocks(level,p,List.of(p),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX(),p.getY(),p.getZ()));c.physicsSystem().getPipeline().teleport(receiver,new Vector3d(8192,9000,8192),new org.joml.Quaterniond());receiver.updateBoundingBox();receiver.updateLastPose();c.addForceLoadTicket(receiver,dev.ryanhcode.sable.api.sublevel.ticket.SubLevelLoadingTicketType.COMMAND_FORCED,net.minecraft.util.Unit.INSTANCE);var target=new SpaceCells.Cell(host,80,8192,9000,8192,0,2200,0,List.of(receiver.getUniqueId()));cells.add(level,target);var nav=SpaceLocalPhysics.navigation(level,cell);var old=data.get(source).orElseThrow();var r=nav.planet().radius()+8000;var state=new SpaceState(new SpaceVector(0,r,0),new SpaceVector(500,0,0));data.put(host,new SpaceTrajectory(old.primary(),level.getGameTime(),state,old.mu()));data.navigate(host,nav);data.put(source,new SpaceTrajectory(old.primary(),level.getGameTime(),new SpaceState(state.position().add(nav.frame().toCosmic(new SpaceVector(30,0,0))),state.velocity().add(nav.frame().toCosmic(new SpaceVector(2,0,0)))),old.mu()));SpaceReentry.entered(level,source,data.sample(source,level.getGameTime()).position());SpaceReentry.entered(level,host,state.position());p=p.east(3);level.setBlockAndUpdate(p,Blocks.GOLD_BLOCK.defaultBlockState());var free=SubLevelAssemblyHelper.assembleBlocks(level,p,List.of(p),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX(),p.getY(),p.getZ()));child=free.getUniqueId();c.physicsSystem().getPipeline().teleport(free,new Vector3d(cell.x()+8,cell.y(),cell.z()),new org.joml.Quaterniond());free.updateBoundingBox();free.updateLastPose();for(int x=510;x<=517;x++)for(int z=510;z<=514;z++)level.getChunk(x,z);});return;}
        if(ticks-at<35)return;
        if(stage==1){stage=2;at=ticks;server(mc,()->{io.github.astelev.around_planet.PlanetConfig.RENDEZVOUS_DISTANCE.set(96.0);SpaceRendezvous.check(ship.getLevel(),SubLevelContainer.getContainer(ship.getLevel()));merged=SpaceOrbitData.get(ship.getLevel().getServer()).get(source).isEmpty();});return;}
        if(stage==2){if(!merged){if(ticks%20==0)server(mc,()->{SpaceRendezvous.check(ship.getLevel(),SubLevelContainer.getContainer(ship.getLevel()));merged=SpaceOrbitData.get(ship.getLevel().getServer()).get(source).isEmpty();});return;}stage=21;at=ticks;return;}
        if(stage==21){require(SubLevelContainer.getContainer(mc.level).getSubLevel(ship.getUniqueId())==identity,"Native client identity was recreated");require(mc.player.getVehicle()==vehicle,"Rider lost native seat");require(SpaceCells.contains(mc.player),"Client no longer sees space membership");var pose=((dev.ryanhcode.sable.sublevel.ClientSubLevel)identity).logicalPose().position();require(Math.abs(pose.x()-8222)<3&&Math.abs(pose.z()-8192)<3,"Client retained source pose: "+pose);require(Math.abs(mc.player.getX()-8222)<8&&Math.abs(mc.player.getZ()-8192)<8,"Seated rider did not arrive in receiver space: "+mc.player.position());server(mc,()->{var c=SubLevelContainer.getContainer(ship.getLevel());require(SpaceCells.get(ship.getLevel()).all().size()==1,"Source cell survived merge");require(c.getSubLevel(child)!=null,"Free child unloaded after arrival");require(c.physicsSystem().getPipeline().getLinearVelocity(ship,new Vector3d()).distance(new Vector3d(2,0,0))<.1,"Arrival relative velocity changed");});net.minecraft.client.Screenshot.grab(mc.gameDirectory,"rendezvous-alpha30.png",mc.getMainRenderTarget(),m->{});stage=3;at=ticks;return;}
        if(stage==3){io.github.astelev.around_planet.AroundPlanet.LOGGER.info("SPACE_RENDEZVOUS_CLIENT PASS native identity, native seat, rider position, child loading, relative velocity and client frame synchronization");mc.stop();stage=4;}
    }
    private static void server(Minecraft mc,Runnable r){mc.getSingleplayerServer().execute(()->{try{r.run();}catch(Throwable e){failure=e;}});}
    private static void require(boolean b,String s){if(!b)throw new AssertionError(s);}
}
